const j = $json || {};
const ctx = $('Edit Context').first().json;
const text = (v) => (v === undefined || v === null || v === '' ? '' : (typeof v === 'object' ? String(v.message || v.description || JSON.stringify(v)) : String(v)));
const vendor = (typeof j.code === 'number' && j.code !== 200) ? ('Kie ' + j.code + ': ' + text(j.msg)) : '';
let message = (text(j.error) || vendor || text(j.failMsg) || text(j.message) || text(j.detail) || text(j.hint) || 'edit failed').slice(0, 500);
const status = (j.error && typeof j.error === 'object' && (j.error.status || j.error.httpCode)) || '';
const inner = message.match(/message\\?":\\?"([^"\\]+)/);
if (inner) message = ($('OpenRouter Image').isExecuted && !/^Region composite/.test(inner[1]) ? 'OpenRouter: ' : '') + inner[1] + (status ? ' (HTTP ' + status + ')' : '');
if ((String(status) === '401' || String(status) === '403') && $('OpenRouter Image').isExecuted) message = 'OpenRouter API key missing or invalid - add it in n8n WF-0 Studio Config (OpenRouter Config node)';
return { json: { message, generationId: ctx.generationId, cardId: ctx.cardId } };

const cfg = $('Load Config').first().json;
const pe = $('Prompt Engine').first().json;
const region = pe.region && typeof pe.region === 'object' ? pe.region : null; // prompt-engine v8.1 region block (Fix an area) - GPT Image 2.5 Sunburst redraws the whole design, region-composite keeps only the area
