if (!prompt) throw new Error('prompt-engine returned an empty edit instruction');
const hasMask = plan.some((p) => p.role === 'mask');
if (hasMask && !region) prompt += '\n\nThe second image is a black-and-white mask of the first image: change ONLY the white region of the mask; every pixel under the black region must stay exactly identical to the first image.';
// region = the Kie Sunburst image-to-image body (UNTESTED lane, same prompt as OpenRouter; the region prompt already names the mask as Image 2); else Nano Banana as before
const body = region ? { model: region.kie_model || 'gpt-image-2-5-sunburst-image-to-image', input: { prompt: String(region.prompt || pe.rendered_prompt).trim().slice(0, 20000), input_urls: urls, aspect_ratio: region.aspect_ratio || pe.aspect_ratio || '1:1', resolution: region.resolution || '1K', background: 'opaque' } } : { model: 'google/nano-banana-edit', input: { prompt: prompt.slice(0, 20000), image_urls: urls, output_format: 'png' } };
return { json: { body, attempt: Number($('Get Generation').first().json.attempt) || 1, has_mask: hasMask, input_roles: plan.map((p) => p.role), region: Boolean(region) } };

const pe = $('Prompt Engine').first().json;
